    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int n = s.length();
        // 预处理阶乘和逆阶乘
        long[] fac = new long[n+1], ifac = new long[n+1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i-1] * i % M;
        }
        ifac[n] = modPow(fac[n], M-2);
        for (int i = n; i >= 1; i--) {
            ifac[i-1] = ifac[i] * i % M;
        }
        // 预处理 2^k
        long[] pow2 = new long[n+1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = pow2[i-1] * 2 % M;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
