def solve():
    MOD = 10**9 + 7
    s = input().strip()
    n = len(s)

    # 预处理阶乘和逆阶乘
    fac = [1] * (n + 1)
    ifac = [1] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % MOD

    # 快速幂求逆元
    def modpow(a, e):
        r = 1
        while e:
            if e & 1:
                r = r * a % MOD
            a = a * a % MOD
            e >>= 1
        return r

    ifac[n] = modpow(fac[n], MOD - 2)
    for i in range(n, 0, -1):
        ifac[i - 1] = ifac[i] * i % MOD

    # 预处理 2^k
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD

    # 组合数
    def comb(x, y):
        if y < 0 or y > x:
            return 0
        return fac[x] * ifac[y] % MOD * ifac[x - y] % MOD

    ans = 0
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] != s[j]:
                A = i                # i 左侧的字符数
                C = n - 1 - j        # j 右侧的字符数
                B = j - i - 1        # i 与 j 之间的字符数
                ans = (ans + comb(A + C, A) * pow2[B]) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
```

